/** The most characters a slug may have. */
const MAX = 80;

/** A title as a lowercase ASCII URL slug of at most `MAX` characters. */
export function slugify(text: string): string {
	const slug = text
		.normalize("NFKD")
		.toLowerCase()
		.replace(/\p{M}+/gu, "")
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-|-$/g, "");
	return slug.slice(0, MAX).replace(/-$/, "");
}
import {expect, it} from "vitest";
import {slugify} from "./slug.ts";

it("makes a slug", () => {
	expect(slugify("Çay Şeker")).toBe("cay-seker");
	expect(slugify("!!!")).toBe("");
});

it.each([41, 79, 80, 81, 300])(
	"retains up to 80 characters from a normalized slug of length %i",
	(length) => {
		expect(slugify("  " + "É".repeat(length) + "!!!")).toBe(
			"e".repeat(Math.min(length, 80)),
		);
	},
);

it("removes a hyphen exposed at the 80-character cutoff", () => {
	expect(slugify("É".repeat(79) + "   next")).toBe("e".repeat(79));
});

it("preserves separators inside the 80-character limit", () => {
	expect(slugify("a".repeat(78) + " next")).toBe("a".repeat(78) + "-n");
});
import fc from "fast-check";
import {expect, it} from "vitest";
import {slugify} from "./slug.ts";

// Law: a slug is never longer than 80 characters, and never ends on a hyphen.
it("a slug stays within its limit", () => {
	fc.assert(
		fc.property(fc.string({maxLength: 300}), (title) => {
			const slug = slugify(title);
			expect(slug.length).toBeLessThanOrEqual(80);
			expect(slug.endsWith("-")).toBe(false);
		}),
		{seed: 1},
	);
});
import fc from "fast-check";
import {expect, it} from "vitest";
import {slugify} from "./slug.ts";

const titles = fc.oneof(
	fc.string({maxLength: 300}),
	fc.array(fc.constantFrom("a", "Z", "9", " ", "-", "é", "🪴", "\u0301"), {
		minLength: 81,
		maxLength: 300,
	}).map((characters) => characters.join("")),
);

it("retains the first 80 normalized characters and removes a final hyphen", () => {
	const cases: Array<[string, string]> = [
		["a".repeat(41), "a".repeat(41)],
		["a".repeat(79), "a".repeat(79)],
		["a".repeat(80), "a".repeat(80)],
		["a".repeat(80) + "b", "a".repeat(80)],
		["a".repeat(300), "a".repeat(80)],
		["a".repeat(79) + " next", "a".repeat(79)],
		["  " + "É".repeat(79) + "   NEXT!", "e".repeat(79)],
		[
			"A practical guide to growing tomatoes on small balconies through the summer months",
			"a-practical-guide-to-growing-tomatoes-on-small-balconies-through-the-summer-mont",
		],
	];
	for (const [title, expected] of cases) {
		expect(slugify(title)).toBe(expected);
	}
});

it("never produces more than 80 characters", () => {
	expect(slugify("a".repeat(300)).length).toBeLessThanOrEqual(80);
	fc.assert(
		fc.property(titles, (title) => {
			expect(slugify(title).length).toBeLessThanOrEqual(80);
		}),
		{seed: 1},
	);
});

it("never produces a trailing hyphen", () => {
	for (const title of [
		"",
		"---",
		"hello ---",
		"a".repeat(39) + " next",
		"a".repeat(79) + " next",
	]) {
		expect(slugify(title).endsWith("-")).toBe(false);
	}
	fc.assert(
